"""company_researcher_mock node: deterministic mock company profile."""

from app.graph.nodes.base import run_node
from app.graph.state import ResearchState


async def _company_researcher(state: ResearchState) -> dict:
    profile = {
        "company_name": state.company_name,
        "industry": state.industry,
        "description": (
            f"Mock profile for {state.company_name}, a {state.industry} company. "
            "This is deterministic placeholder data generated by company_researcher_mock; "
            "no real research was performed."
        ),
        "size_estimate": "unknown",
        "headquarters": "unknown",
        "founded_year": None,
        "website": None,
        "key_products": [],
        "source": "company_researcher_mock (Phase 1 mock)",
        "mock": True,
    }
    return {
        "company_profile": profile,
        "_metadata_details": {"company": state.company_name},
    }


async def company_researcher_mock(state: ResearchState) -> dict:
    """Return a deterministic mock company profile (not real research)."""
    if not state.company_name:
        raise ValueError("company_name is required for company research.")
    return await run_node(
        node_name="company_researcher_mock",
        state=state,
        node_fn=_company_researcher,
        mock=True,
    )
